  ($qb$HEAIL-TMP-FIB-011$qb$, $qb$A7-05$qb$, $qb$FIB$qb$, $qb$Leaving gaps between appointments means one overrun does not affect every later ______.$qb$, $qb$appointment$qb$, $qb$overrun$qb$, $qb$time$qb$, $qb$gap$qb$, $qb$minute$qb$, 5, 0, 0, 0, 0, true),
  ($qb$HEAIL-TMP-FIB-012$qb$, $qb$A7-05$qb$, $qb$FIB$qb$, $qb$Handling a short task immediately can save the time later spent ______ it.$qb$, $qb$revisiting$qb$, $qb$filing$qb$, $qb$renaming$qb$, $qb$printing$qb$, $qb$scheduling$qb$, 5, 0, 0, 0, 0, true),
